'use client';

import * as React from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { LoaderCircle, Pause, Play } from 'lucide-react';
import { matterixFieldLabel } from '@/lib/labels';
import type { MatterixExecutionDetail } from '../types/matterixExecution';
import { isActiveMatterixStatus } from '../utils/matterixExecution';

// Generated by integrations/matterix/tools/export_station_twin.py: meshes named <link|shell|obj>_<name>__<material>,
// baked in the base-link frame (Z up) with the USD materials.
const TWIN_GLB = '/twin/pipetting_station.glb';
const TWIN_JSON = '/twin/pipetting_station.json';
const HIGHLIGHT = 0xf97316;
const CONSUMABLE_MIN_OPACITY = 0.65;
const CONSUMABLE_EDGES = new THREE.LineBasicMaterial({ color: 0x334155, transparent: true, opacity: 0.6 });
const SHELL_EDGES = new THREE.LineBasicMaterial({ color: 0x475569, transparent: true, opacity: 0.55 });

type Pose = number[]; // x, y, z, qx, qy, qz, qw in the base-link frame

interface TwinJoint {
  name: string;
  type: 'prismatic' | 'revolute';
  parent: string;
  child: string;
  axis: [number, number, number];
  anchor: [number, number, number];
}

interface TwinMeta {
  joints: TwinJoint[];
  fixed: Array<{ parent: string; child: string }>;
  attached: Record<string, string>;
  object_rest_xyz_qxyzw: Record<string, Pose>;
}

interface TwinFrame {
  t: number;
  joints: Record<string, number>;
  /** Consumables displaced since the scene reset; null for records made before the bridge reported them. */
  objects: Record<string, Pose> | null;
}

interface TwinScene {
  meta: TwinMeta;
  renderer: THREE.WebGLRenderer;
  camera: THREE.PerspectiveCamera;
  frameStation: () => void;
  scene: THREE.Scene;
  links: Map<string, THREE.Group>;
  objects: Map<string, THREE.Object3D>;
  restInverse: Map<string, THREE.Matrix4>;
  /** Enclosure panels and doors, then the base frame: the two groups whose opacity the sliders scale. */
  shell: Fadable[];
  frame: Fadable[];
  linkMaterials: Map<string, THREE.MeshStandardMaterial[]>;
}

interface Fadable {
  material: THREE.MeshStandardMaterial;
  /** The USD opacity, so glass stays more see-through than the sheet metal next to it. */
  opacity: number;
}

function fade(group: Fadable[], scale: number) {
  for (const { material, opacity } of group) {
    const solid = opacity * scale >= 1;
    material.opacity = opacity * scale;
    // a see-through panel must not write depth, or it hides the mechanism behind it
    material.depthWrite = solid;
    if (material.transparent === solid) {
      material.transparent = !solid;
      material.needsUpdate = true;
    }
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function stationTwinFrames(detail: MatterixExecutionDetail): TwinFrame[] {
  return detail.samples.flatMap((sample) => {
    const t = detail.scope === 'protocol' ? sample.protocol_time_s : sample.sim_time_s;
    const semantics = sample.semantics;
    if (sample.scene_id !== 'pipetting_realtime' || typeof t !== 'number' || !isRecord(semantics)) return [];
    // records made before jointsSI existed keep the same values under device_state.joint_positions
    const joints = semantics.jointsSI ?? (isRecord(semantics.device_state) && semantics.device_state.joint_positions);
    if (!isRecord(joints)) return [];
    return [
      {
        t,
        joints: joints as Record<string, number>,
        objects: isRecord(semantics.object_poses) ? (semantics.object_poses as Record<string, Pose>) : null,
      },
    ];
  });
}

function poseMatrix(pose: Pose): THREE.Matrix4 {
  return new THREE.Matrix4().compose(
    new THREE.Vector3(pose[0], pose[1], pose[2]),
    new THREE.Quaternion(pose[3], pose[4], pose[5], pose[6]),
    new THREE.Vector3(1, 1, 1)
  );
}

function lerpPose(a: Pose, b: Pose, u: number): Pose {
  const position = new THREE.Vector3(a[0], a[1], a[2]).lerp(new THREE.Vector3(b[0], b[1], b[2]), u);
  const rotation = new THREE.Quaternion(a[3], a[4], a[5], a[6]).slerp(new THREE.Quaternion(b[3], b[4], b[5], b[6]), u);
  return [...position.toArray(), ...rotation.toArray()];
}

async function buildTwin(container: HTMLDivElement): Promise<TwinScene> {
  const [gltf, meta] = await Promise.all([
    new GLTFLoader().loadAsync(TWIN_GLB),
    fetch(TWIN_JSON).then((response) => {
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return response.json() as Promise<TwinMeta>;
    }),
  ]);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(window.devicePixelRatio);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  const scene = new THREE.Scene();
  // image-based light, without which the aluminium and steel parts render as flat grey
  scene.environment = new THREE.PMREMGenerator(renderer).fromScene(new RoomEnvironment(), 0.04).texture;
  const sun = new THREE.DirectionalLight(0xffffff, 1.2);
  sun.position.set(1.5, 2, 3);
  scene.add(sun);

  const links = new Map<string, THREE.Group>();
  const link = (name: string) => {
    let group = links.get(name);
    if (!group) {
      group = new THREE.Group();
      links.set(name, group);
      scene.add(group);
    }
    return group;
  };
  // Every mesh sits at its rest pose in the base frame, so nesting identity groups along the joint tree is enough:
  // moving a group by its joint value carries all of its descendants.
  for (const { parent, child } of [...meta.joints, ...meta.fixed]) link(parent).add(link(child));

  const shell: Fadable[] = [];
  const frame: Fadable[] = [];
  const linkMaterials = new Map<string, THREE.MeshStandardMaterial[]>();
  const objects = new Map<string, THREE.Object3D>();
  const meshes: THREE.Mesh[] = [];
  gltf.scene.traverse((node) => {
    if (node instanceof THREE.Mesh) meshes.push(node);
  });
  for (const mesh of meshes) {
    const [kind, name] = [
      mesh.name.slice(0, mesh.name.indexOf('_')),
      mesh.name.slice(mesh.name.indexOf('_') + 1, mesh.name.lastIndexOf('__')),
    ];
    mesh.matrix.identity();
    mesh.matrixAutoUpdate = false;
    if (kind === 'obj') {
      // one consumable can have several materials (body, cap liner), so it is a group of meshes
      let group = objects.get(name);
      if (!group) {
        group = new THREE.Group();
        group.matrixAutoUpdate = false;
        objects.set(name, group);
        scene.add(group);
      }
      group.add(mesh);
      // the USD glass and clear plastics (opacity 0.03-0.35) all but vanish next to the see-through enclosure
      const material = mesh.material as THREE.MeshStandardMaterial;
      material.opacity = Math.max(material.opacity, CONSUMABLE_MIN_OPACITY);
      material.depthWrite = true;
      // near-white labware on a near-white deck: an outline keeps each bottle, vial and tip distinct
      mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry, 40), CONSUMABLE_EDGES));
      continue;
    }
    // every link gets its own copy so it can be faded or highlighted without touching its neighbours
    const material = (mesh.material as THREE.MeshStandardMaterial).clone();
    mesh.material = material;
    if (kind === 'shell') {
      shell.push({ material, opacity: material.opacity });
      mesh.renderOrder = 2;
      // outline the panels so the enclosure still reads as a solid cabinet when it is mostly see-through
      mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry, 30), SHELL_EDGES));
    } else if (name === 'base') {
      frame.push({ material, opacity: material.opacity });
      mesh.renderOrder = 1;
    } else {
      linkMaterials.set(name, [...(linkMaterials.get(name) ?? []), material]);
    }
    link(name).add(mesh);
  }

  const camera = new THREE.PerspectiveCamera(40, 1, 0.05, 50);
  camera.up.set(0, 0, 1);
  const box = new THREE.Box3().setFromObject(scene);
  const center = box.getCenter(new THREE.Vector3());
  const corners = [0, 1, 2, 3, 4, 5, 6, 7].map(
    (i) =>
      new THREE.Vector3(i & 1 ? box.max.x : box.min.x, i & 2 ? box.max.y : box.min.y, i & 4 ? box.max.z : box.min.z)
  );
  container.appendChild(renderer.domElement);
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.target.copy(center);
  /** Look from the bridge recording's overview side, as close as still shows the whole station at this aspect. */
  const frameStation = () => {
    let distance = box.getSize(new THREE.Vector3()).length() * 2;
    for (let pass = 0; pass < 3; pass++) {
      camera.position.set(1.3, 1.65, 0.9).normalize().multiplyScalar(distance).add(center);
      camera.lookAt(center);
      camera.updateMatrixWorld();
      const extent = Math.max(
        ...corners.map((corner) => {
          const ndc = corner.clone().project(camera);
          return Math.max(Math.abs(ndc.x), Math.abs(ndc.y));
        })
      );
      distance *= extent * 1.1;
    }
    controls.update();
  };
  controls.addEventListener('change', () => renderer.render(scene, camera));

  return {
    meta,
    renderer,
    camera,
    frameStation,
    scene,
    links,
    objects,
    restInverse: new Map(
      Object.entries(meta.object_rest_xyz_qxyzw).map(([name, pose]) => [name, poseMatrix(pose).invert()])
    ),
    shell,
    frame,
    linkMaterials,
  };
}

/** The two samples around time t and how far t lies between them. */
function bracket(frames: TwinFrame[], t: number): [TwinFrame, TwinFrame, number] {
  const next = Math.max(
    1,
    frames.findIndex((frame) => frame.t >= t)
  );
  const [a, b] = frames.length === 1 ? [frames[0], frames[0]] : [frames[next - 1], frames[next]];
  return [a, b, b.t > a.t ? Math.min(1, Math.max(0, (t - a.t) / (b.t - a.t))) : 0];
}

function isMoving(a: TwinFrame, b: TwinFrame, joint: string): boolean {
  return Math.abs((b.joints[joint] ?? 0) - (a.joints[joint] ?? 0)) > 1e-4;
}

/** Pose the twin at time t, linear between the two surrounding samples, and highlight the links in motion. */
function applyTime(twin: TwinScene, frames: TwinFrame[], t: number) {
  const [a, b, u] = bracket(frames, t);

  const axis = new THREE.Vector3();
  const anchor = new THREE.Vector3();
  for (const joint of twin.meta.joints) {
    const [qa, qb] = [a.joints[joint.name] ?? 0, b.joints[joint.name] ?? 0];
    const q = qa + (qb - qa) * u;
    const highlight = isMoving(a, b, joint.name) ? HIGHLIGHT : 0;
    for (const material of twin.linkMaterials.get(joint.child) ?? []) material.emissive.setHex(highlight);
    const group = twin.links.get(joint.child)!;
    axis.fromArray(joint.axis);
    if (joint.type === 'prismatic') {
      group.position.copy(axis).multiplyScalar(q);
    } else {
      group.quaternion.setFromAxisAngle(axis, q);
      anchor.fromArray(joint.anchor);
      group.position.copy(anchor).sub(anchor.clone().applyQuaternion(group.quaternion));
    }
  }
  twin.scene.updateMatrixWorld(true);

  for (const [name, object] of twin.objects) {
    const [pa, pb] = [a.objects?.[name], b.objects?.[name]];
    const pose = pa && pb ? lerpPose(pa, pb, u) : (pb ?? pa);
    const carrier = a.objects === null ? twin.links.get(twin.meta.attached[name]) : undefined;
    if (pose) object.matrix.multiplyMatrices(poseMatrix(pose), twin.restInverse.get(name)!);
    // shortcut: old records carry no consumable poses, so initially held items follow their tool for the whole
    // replay; re-run the task on a bridge that reports object_poses to see pick/drop.
    else if (carrier) object.matrix.copy(carrier.matrixWorld);
    else object.matrix.identity();
  }
  twin.scene.updateMatrixWorld(true);
  twin.renderer.render(twin.scene, twin.camera);
}

/**
 * Without a detail (no run yet, or its record failed to load) the station is shown at its rest pose.
 * `replay={false}` is the standalone twin page: no timeline, the model holds the newest sample and the canvas fills
 * its parent with the opacity controls laid over it.
 */
export default function StationTwinView({
  detail,
  replay = true,
}: {
  detail: MatterixExecutionDetail | null;
  replay?: boolean;
}) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [twin, setTwin] = React.useState<TwinScene | null>(null);
  const [loadError, setLoadError] = React.useState<string | null>(null);
  const frames = React.useMemo(() => (detail ? stationTwinFrames(detail) : []), [detail]);
  const start = frames[0]?.t ?? 0;
  const end = frames.at(-1)?.t ?? 0;
  // null follows the newest sample, which is the live view while a task is running
  const [cursor, setCursor] = React.useState<number | null>(null);
  const [playing, setPlaying] = React.useState(false);
  const [shellOpacity, setShellOpacity] = React.useState(0.25);
  const [frameOpacity, setFrameOpacity] = React.useState(1);
  const time = Math.min(end, Math.max(start, cursor ?? end));

  React.useEffect(() => {
    const container = containerRef.current!;
    let built: TwinScene | null = null;
    let cancelled = false;
    let framed = false;
    const resize = new ResizeObserver(() => {
      if (!built) return;
      built.renderer.setSize(container.clientWidth, container.clientHeight);
      built.camera.aspect = container.clientWidth / container.clientHeight;
      built.camera.updateProjectionMatrix();
      // only until the user takes the camera; after that a resize must not undo their view
      if (!framed) built.frameStation();
      framed = true;
      built.renderer.render(built.scene, built.camera);
    });
    buildTwin(container)
      .then((value) => {
        if (cancelled) {
          value.renderer.dispose();
          value.renderer.domElement.remove();
          return;
        }
        built = value;
        resize.observe(container);
        setTwin(value);
      })
      .catch((reason: unknown) => {
        setLoadError(
          `孪生模型加载失败（${reason instanceof Error ? reason.message : String(reason)}）。` +
            '模型不随仓库分发，请先运行 integrations/matterix/tools/export_station_twin.py 生成。'
        );
      });
    return () => {
      cancelled = true;
      resize.disconnect();
      built?.renderer.dispose();
      built?.renderer.domElement.remove();
    };
  }, []);

  React.useEffect(() => {
    if (!twin) return;
    fade(twin.shell, shellOpacity);
    fade(twin.frame, frameOpacity);
    if (frames.length > 0) applyTime(twin, frames, time);
    else twin.renderer.render(twin.scene, twin.camera);
  }, [twin, frames, time, shellOpacity, frameOpacity]);

  React.useEffect(() => {
    if (!playing) return;
    let last = performance.now();
    let handle = requestAnimationFrame(function tick(now) {
      const dt = (now - last) / 1000;
      last = now;
      setCursor((value) => Math.min(end, (value ?? end) + dt));
      handle = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(handle);
  }, [playing, end]);

  if (playing && time >= end) setPlaying(false);

  const moving = React.useMemo(() => {
    if (frames.length === 0) return [];
    const [a, b] = bracket(frames, time);
    return Object.keys(b.joints).filter((joint) => isMoving(a, b, joint));
  }, [frames, time]);
  const live = cursor === null && detail !== null && isActiveMatterixStatus(detail.status);
  const slider = 'h-1.5 cursor-pointer accent-blue-600';
  return (
    <div className={replay ? 'space-y-3' : 'relative h-full'}>
      <div
        ref={containerRef}
        className={`overflow-hidden bg-gradient-to-b from-slate-50 to-slate-300 ${
          replay
            ? 'relative h-[520px] w-full rounded-lg border border-gray-200 dark:border-slate-700'
            : 'absolute inset-0'
        }`}
      >
        {!twin && !loadError && (
          <p className="absolute inset-0 flex items-center justify-center gap-2 text-sm text-gray-500 dark:text-gray-400">
            <LoaderCircle className="h-4 w-4 animate-spin" />
            正在加载移液站模型…
          </p>
        )}
        {loadError && (
          <p className="absolute inset-0 flex items-center justify-center p-6 text-center text-sm text-red-600 dark:text-red-400">
            {loadError}
          </p>
        )}
      </div>

      {!replay ? null : frames.length === 0 ? (
        <p className="text-sm text-gray-500 dark:text-gray-400">
          这次运行没有移液站关节样本（尚未开始执行，或用的是其他场景），模型显示为初始姿态。
        </p>
      ) : (
        <div className="flex flex-wrap items-center gap-3 text-xs text-gray-600 dark:text-gray-300">
          <button
            type="button"
            aria-label={playing ? '暂停' : '回放'}
            onClick={() => {
              if (!playing && time >= end) setCursor(start);
              else if (cursor === null) setCursor(time);
              setPlaying(!playing);
            }}
            className="inline-flex h-7 w-7 items-center justify-center rounded-md border border-gray-300 hover:bg-gray-50 dark:border-slate-600 dark:hover:bg-slate-800"
          >
            {playing ? <Pause className="h-3.5 w-3.5" /> : <Play className="h-3.5 w-3.5" />}
          </button>
          <input
            type="range"
            aria-label="回放时间"
            className={`${slider} min-w-40 flex-1`}
            min={start}
            max={end}
            step="any"
            value={time}
            onChange={(event) => {
              setPlaying(false);
              setCursor(Number(event.target.value));
            }}
          />
          <span className="w-32 text-right font-mono tabular-nums">
            {time.toFixed(2)} / {end.toFixed(2)} s
          </span>
          <button
            type="button"
            disabled={cursor === null}
            onClick={() => {
              setPlaying(false);
              setCursor(null);
            }}
            className="rounded-md border border-gray-300 px-2 py-1 hover:bg-gray-50 disabled:opacity-50 dark:border-slate-600 dark:hover:bg-slate-800"
          >
            {live ? '实时跟随中' : '跳到最新'}
          </button>
        </div>
      )}

      <div
        className={`flex flex-wrap items-center gap-x-6 gap-y-2 text-xs ${
          replay
            ? 'text-gray-600 dark:text-gray-300'
            : 'absolute bottom-4 left-6 rounded-md bg-white/70 px-3 py-2 text-slate-700 backdrop-blur'
        }`}
      >
        <label className="flex items-center gap-2">
          外壳与门透明度
          <input
            type="range"
            className={slider}
            min={0}
            max={0.95}
            step={0.05}
            value={1 - shellOpacity}
            onChange={(event) => setShellOpacity(1 - Number(event.target.value))}
          />
        </label>
        <label className="flex items-center gap-2">
          机架与台面透明度
          <input
            type="range"
            className={slider}
            min={0}
            max={0.95}
            step={0.05}
            value={1 - frameOpacity}
            onChange={(event) => setFrameOpacity(1 - Number(event.target.value))}
          />
        </label>
        <span className="flex items-center gap-1.5">
          <span className="inline-block h-2.5 w-2.5 rounded-sm bg-orange-500" />
          正在运动：{moving.length > 0 ? moving.map(matterixFieldLabel).join('、') : '无'}
        </span>
      </div>
      <p className={replay ? 'text-xs text-gray-500 dark:text-gray-400' : 'hidden'}>
        模型由移液站 USD 导出，姿态来自{detail?.source === 'simulation' ? ' Isaac Sim 仿真' : '执行'}
        样本中的关节位置（约 0.5 s 一个样本，中间线性插值）。拖动旋转，滚轮缩放，右键平移。
      </p>
    </div>
  );
}
